using System;
using System.Drawing;
using System.IO;

namespace GenDaLangDu {
  /// <summary>多多五笔托盘指示器图标模板（从 duoIME.ime 用 ExtractIconEx 提取）。
  /// 中文状态：icon_5（"中"字形）与 icon_23（橙红禁止圈，有时显示）；
  /// 英文状态：icon_2 与 icon_22（键盘形，两个几乎相同的变体）。</summary>
  internal static class TrayImeTemplates {
    public const string Icon5Png =
      "";

    public const string Icon23Png =
      "";

    public const string Icon2Png =
      "";

    public const string Icon22Png =
      "";

    public static Bitmap Load(string base64) {
      byte[] data = Convert.FromBase64String(base64);
      using (MemoryStream ms = new MemoryStream(data)) {
        return new Bitmap(ms);
      }
    }
  }
}
